VALUES('OBD_COMPLETE_MIS_CUMULATIVE', '<OBD_DBSCHEMA>.OBD_EVR_DETAILS', 'TOTAL_COUNT', 'D', 3, '<DB_USERNAME>', '<DB_PASSWORD>', '<DB_IP>', '<DB_NAME>', '<OBD_DBSCHEMA>', 'SELECT DATE_TRUNC(''hour'', A.GEN_TIME) AS GEN_DATE, EXTRACT(HOUR FROM A.GEN_TIME) AS GEN_HOUR, A.EVR_CAUSE, A.EVR_EVENT, A.EVR_REASON, A.CAMP_ID, A.DURATION, B.CLIENT_ID, B.LIST_REC_COUNT, COUNT(*) AS TOTAL_COUNT FROM <:EVR_TABLE> A JOIN OBD_CAMPAIGN_MAST B ON A.CAMP_ID = B.CAMP_ID WHERE A.GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY DATE_TRUNC(''hour'', A.GEN_TIME), EXTRACT(HOUR FROM A.GEN_TIME), A.EVR_CAUSE, A.EVR_EVENT, A.EVR_REASON, A.CAMP_ID, A.DURATION, B.CLIENT_ID, B.LIST_REC_COUNT;');


